<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {mixTracks,mixChallenges} from '../../data/playground.js';
import {mixScore,validateMix} from '../../room/creativeTools.js';
import {createMixEngine,renderMixWav} from '../../audio/mixEngine.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {useInteractionAudio} from '../../composables/useInteractionAudio.js';
import {recordActivity} from '../../room/activityLog.js';
const initial=()=>({version:1,task:0,channels:mixChallenges[0].initial.map(c=>({...c,mute:false,solo:false})),cleared:[]});
const {state,saved}=useLocalDraft('hitori-room:mix:v1',initial(),validateMix),audio=useInteractionAudio('mix'),playing=ref(false),reference=ref(false),busy=ref(false),message=ref('先听自己的版本，再切到参考。每关只需修复一类问题，达到 85 分即可完成。');
const task=computed(()=>mixChallenges[state.value.task]),score=ref(null);
const engine=createMixEngine({createContext:()=>new (window.AudioContext||window.webkitAudioContext)(),isHidden:()=>document.hidden});let generation=0;
const channels=computed(()=>reference.value?task.value?.target.map(c=>({...c,mute:false,solo:false}))||state.value.channels:state.value.channels);
function stop(){generation++;engine.stop();playing.value=false;}
async function play(){stop();const token=++generation;if(!audio.enabled.value&&!await audio.setEnabled(true)){message.value='当前浏览器无法开启声音。';return;}if(token!==generation||document.hidden)return;playing.value=await engine.play(channels.value,audio.volume.value);if(token!==generation)engine.stop();}
function select(i){stop();state.value.task=i;reference.value=false;score.value=null;state.value.channels=(mixChallenges[i]?.initial||mixChallenges[0].target).map(c=>({...c,mute:false,solo:false}));}
function check(){score.value=mixScore(task.value,state.value.channels);if(state.value.channels.some(c=>c.mute||c.solo)){score.value=0;message.value='先取消静音和独奏，让四条轨道一起参加核对。';return;}if(score.value>=85){if(!state.value.cleared.includes(state.value.task))state.value.cleared.push(state.value.task);message.value='声音重新站到一起了。这一关已完成。';recordActivity('mix',`${task.value.name} · ${score.value} 分`,task.value.id);}else message.value='再和参考轮流听一下，也可以对照小提示继续调整。';}
async function exportWav(){busy.value=true;try{const blob=await renderMixWav(state.value.channels,window.OfflineAudioContext||window.webkitOfflineAudioContext);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hitori-my-mix.wav';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='8 秒立体声 WAV 已导出。';recordActivity('mix','导出自己的合奏混音');}catch{message.value='这台浏览器暂时无法导出 WAV。';}finally{busy.value=false;}}
watch(channels,()=>{if(playing.value)engine.update(channels.value);},{deep:true});watch(audio.enabled,value=>{if(!value)stop();});watch(audio.volume,value=>engine.volume(value));function hidden(){if(document.hidden)stop();}document.addEventListener('visibilitychange',hidden);onBeforeRouteLeave(stop);onBeforeUnmount(()=>{stop();engine.dispose();document.removeEventListener('visibilitychange',hidden);});
</script>
<template><section class="room-panel" aria-labelledby="mix-title"><div class="pg-heading"><div><p class="pg-kicker">FIND THE BALANCE / それぞれの、居場所</p><h2 id="mix-title">让每一种声音，都有自己的位置。</h2><p class="room-intro">四条本站原创合成音轨，三次修复任务。调整音量、声像和高频，让合奏重新平衡。</p></div><span class="pg-number">19</span></div><div class="pg-toolbar"><button v-for="(t,i) in mixChallenges" :key="t.id" :aria-pressed="state.task===i" @click="select(i)">{{state.cleared.includes(i)?'✓ ':''}}{{i+1}} · {{t.name}}</button><button :aria-pressed="state.task===3" @click="select(3)">自由混音</button></div><div class="pg-surface"><h3>{{task?.name||'这一段，由你来决定'}}</h3><p>{{task?.text||'调整全部参数，试试静音与独奏，导出自己喜欢的版本。'}}</p><div class="pg-toolbar"><button id="mix-play" class="primary" :disabled="playing" @click="play">循环试听 ▶</button><button :disabled="!playing" @click="stop">停止</button><button v-if="task" id="mix-reference" :aria-pressed="reference" @click="reference=!reference">{{reference?'正在听参考 · 切回我的版本':'A/B · 听参考版本'}}</button><span class="pg-small">{{playing?'正在播放 8 秒循环':'声音已停止'}}</span></div></div><div class="mix-console"><fieldset v-for="(track,i) in mixTracks" :key="track.id" :disabled="reference" :style="{'--track-color':track.color}"><legend>{{track.label}}</legend><span class="mix-channel-number">0{{i+1}}</span><label>音量 · {{Math.round(state.channels[i].volume*100)}}%<input v-model.number="state.channels[i].volume" :data-mix-volume="i" type="range" min="0" max="1" step=".01"></label><label>声像 · {{state.channels[i].pan===0?'中':state.channels[i].pan<0?'左':'右'}} {{Math.abs(state.channels[i].pan).toFixed(2)}}<input v-model.number="state.channels[i].pan" type="range" min="-1" max="1" step=".05"></label><label>高频 · {{state.channels[i].tone}} dB<input v-model.number="state.channels[i].tone" type="range" min="-12" max="12" step=".5"></label><div class="pg-checks"><label><input v-model="state.channels[i].mute" type="checkbox">静音</label><label><input v-model="state.channels[i].solo" type="checkbox">独奏</label></div><details v-if="task"><summary>看一眼参考刻度</summary><p>音量 {{Math.round(task.target[i].volume*100)}}%<br>声像 {{task.target[i].pan}}<br>高频 {{task.target[i].tone}} dB</p></details></fieldset></div><div class="pg-toolbar"><button v-if="task" id="mix-check" class="primary" :disabled="reference" @click="check">核对这一版</button><span v-if="score!==null" class="pg-score">{{score}} / 100</span><button id="mix-export" :disabled="busy" @click="exportWav">{{busy?'正在渲染…':'导出我的版本 WAV'}}</button></div><p class="pg-status" role="status">{{message}}</p><p class="pg-small">{{saved?'推子设置自动保存在本机。':'本机存档暂不可用。'}} A/B 参考不会改写你的推子。离开页面或关闭互动声音会停止试听。</p></section></template>
<style scoped>.mix-console{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.mix-console fieldset{min-width:0;border:1px solid #b49aaa;border-top:5px solid var(--track-color);padding:20px 13px;display:grid;gap:20px;background:#e9dfe3}.mix-console legend{font-size:12px;padding:0 8px}.mix-console fieldset>label{display:grid;gap:13px;font-size:11px}.mix-console input[type=range]{width:100%;accent-color:#996582;padding:0;border:0;min-height:34px}.mix-channel-number{font:24px monospace;color:#ab8a9d}.mix-console details{font-size:10px;line-height:1.8}.mix-console summary{cursor:pointer;min-height:30px}.pg-surface p{font-size:12px;line-height:1.9}@media(max-width:760px){.mix-console{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}}</style>
